#!/usr/bin/env -S uv run --script
# Synced from bootstrap: macos/tools/cli/tasks/cleanupDS.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Cleanup .DS_Store files from the system"
# MISE hide=true
# MISE dir="."
# MISE tools={uv="latest", python="3.14"}

import os
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, os.path.expanduser("~/.config/mise/tasks/_scripts"))
import helpers  # noqa: E402


def main():
  # If no argument is passed (or it is empty), use $HOME
  folder = sys.argv[1] if len(sys.argv) > 1 and sys.argv[1] else os.environ.get("HOME", "")

  helpers.print_header(f"Cleaning up .DS_Store files in {folder} ...")
  # The errors of find go to /dev/null, and its code does not stop the task.
  try:
    subprocess.run(
      ["find", folder, "-type", "f", "-name", ".DS_Store", "-not", "-path", "*/Library/*", "-ls", "-delete"],
      check=False,
      stderr=subprocess.DEVNULL,
    )
  except FileNotFoundError:
    pass


if __name__ == "__main__":
  main()
